class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        # Start at position 0, which is (0, 0)
        row, col = 0, 0

        # Process each command
        for command in commands:
            if command == "RIGHT":
                col += 1
            elif command == "LEFT":
                col -= 1
            elif command == "DOWN":
                row += 1
            elif command == "UP":
                row -= 1

        # Convert final row, col back to position
        return row * n + col

from collections import defaultdict
from typing import List

class Solution:
    def winningPlayerCount(self, n: int, pick: List[List[int]]) -> int:
        # Count how many balls of each color each player picked
        player_color_count = defaultdict(dict)

        for player, color in pick:
            player_color_count[player][color] = player_color_count[player].get(color, 0) + 1

        winners = 0

        # Check each player from 0 to n-1
        for i in range(n):
            # Find the maximum count of any single color that player i picked
            max_count = 0
            if i in player_color_count:
                for color in player_color_count[i]:
                    max_count = max(max_count, player_color_count[i][color])

            # Player i wins if they have strictly more than i balls of the same color
            if max_count > i:
                winners += 1

        return winners

class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        # Calculate cost to make all rows palindromic
        rows_cost = 0
        for i in range(m):
            # For each row, check symmetric pairs
            for j in range(n // 2):
                # Compare position j with position (n-1-j)
                if grid[i][j] != grid[i][n - 1 - j]:
                    rows_cost += 1

        # Calculate cost to make all columns palindromic
        cols_cost = 0
        for j in range(n):
            # For each column, check symmetric pairs
            for i in range(m // 2):
                # Compare position i with position (m-1-i)
                if grid[i][j] != grid[m - 1 - i][j]:
                    cols_cost += 1

        # Return the minimum cost
        return min(rows_cost, cols_cost)
